import requests
import pandas as pd
import json

def fetch_yankees_1977_bb_ab():
    url = "https://www.baseball-reference.com/teams/NYY/1977.shtml"
    try:
        resp = requests.get(url, timeout=30)
        resp.raise_for_status()
    except Exception as e:
        return {"error": f"Request failed: {e}", "source": url}

    try:
        tables = pd.read_html(resp.text)
    except Exception as e:
        return {"error": f"Failed to parse tables: {e}", "source": url}

    df = None
    for t in tables:
        if isinstance(t.columns, (list, tuple)):
            cols = [str(c) for c in t.columns]
            if 'Player' in cols and 'BB' in cols and 'AB' in cols:
                df = t
                break

    if df is None:
        return {"error": "Could not locate a player batting table with BB and AB columns", "source": url}

    # Remove potential header rows scattered in the table
    if 'Player' in df.columns:
        df = df[df['Player'] != 'Player']

    # Normalize numeric columns
    for c in ['BB', 'AB']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')

    if 'BB' not in df.columns or 'AB' not in df.columns:
        return {"error": "Required columns BB/AB not found after parsing", "source": url}

    # Some tables include 'BB' and 'AB' as NaN for non-players; ignore those rows
    df_valid = df.dropna(subset=['BB', 'AB'])
    if df_valid.empty:
        return {"error": "No valid BB/AB data found", "source": url}

    max_bb = int(df_valid['BB'].max())
    leaders = df_valid[df_valid['BB'] == max_bb][['Player', 'BB', 'AB']].copy()

    results = []
    for _, row in leaders.iterrows():
        name = str(row['Player']).strip()
        bb = int(row['BB'])
        ab = int(row['AB'])
        results.append({"Name": name, "BB": bb, "AB": ab})

    return {"leaders": results, "maxBB": max_bb, "source": url}

if __name__ == "__main__":
    out = fetch_yankees_1977_bb_ab()
    print(json.dumps(out, indent=2))

